   &strings.changelog.ascii-case-folding;
   &strings.changelog.needle-empty;


    8.0.0
    needle को रूपमा एउटा &integer; pass गर्न अब support गरिँदैन।



    7.3.0
    needle को रूपमा एउटा &integer; pass गर्ने कार्य deprecated गरिएको छ।



    7.1.0
    Negative offsets का लागि support थपिएको छ।

  &reftitle.examples;



   stripos का उदाहरणहरू


<?php
$findme    = 'a';
$mystring1 = 'xyz';
$mystring2 = 'ABC';

$pos1 = stripos($mystring1, $findme);
$pos2 = stripos($mystring2, $findme);

// Nope, 'a' is certainly not in 'xyz'
if ($pos1 === false) {
    echo "The string '$findme' was not found in the string '$mystring1'", PHP_EOL;
}

// Note our use of !==.  Simply != would not work as expected
// because the position of 'a' is the 0th (first) character.
if ($pos2 !== false) {
    echo "We found '$findme' in '$mystring2' at position $pos2", PHP_EOL;
}
?>
